O = "ledgers/E3/scripts/E3-f-r18/out/"
rows = []
def add(rid, check, location, status, evidence, fix=None):
    r = {"id": rid, "check": check, "location": location, "status": status, "evidence": evidence}
    if status != "PASS":
        r["fix"] = fix
    rows.append(r)
def carry(rid, files, extra=""):
    prev = old[rid]
    add(rid, prev["check"], prev["location"], "PASS",
        f"Carried from round 15 ({files} byte-identical since the previous pin dde0486b): " + prev["evidence"].split(": ", 1)[-1][:900] + extra)
def redo(rid, evidence, location=None):
    prev = old[rid]
    add(rid, prev["check"], location or prev["location"], "PASS", evidence)

